namespace ghidra.file.formats.android.dex.analyzer;

using ghidra.app.services;
using ghidra.app.services;
using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.app.util.importer;
using ghidra.file.analyzers;
using ghidra.file.formats.android.cdex;
using ghidra.file.formats.android.dex.format;
using ghidra.file.formats.android.dex.util;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.util.exception;
using ghidra.util.task;

public class DexCondenseFillerBytesAnalyzer : FileFormatAnalyzer {

	/* @Override */
	public bool analyze(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		AlignmentDataType alignmentDataType = new AlignmentDataType();

		Address address = toAddr(program, DexUtil.METHOD_ADDRESS);
		MemoryBlock block = program.getMemory().getBlock(address);

		if (block == null) {
			log.appendMsg("Can't locate block with method byte code!");
			return false;
		}

		AddressSet blockSet = new AddressSet(block.getStart(), block.getEnd());

		AddressSetView undefinedSet =
			program.getListing().getUndefinedRanges(blockSet, true, monitor);

		monitor.setMaximum(undefinedSet.getNumAddressRanges());
		monitor.setProgress(0);
		monitor.setMessage("DEX: condensing filler bytes");

		AddressRangeIterator addressRanges = undefinedSet.getAddressRanges();
		while (addressRanges.hasNext()) {
			monitor.checkCancelled();
			monitor.incrementProgress(1);
			AddressRange addressRange = addressRanges.next();
			if (isRangeAllSameBytes(program, addressRange, (byte) 0xff, monitor)) {
				program.getListing()
						.createData(addressRange.getMinAddress(), alignmentDataType,
							(int) addressRange.getLength());
			}
		}

		//collapseFillerBytes( program, monitor );

		return true;
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		ByteProvider provider = MemoryByteProvider.createProgramHeaderByteProvider(program, false);
		return DexConstants.isDexFile(provider) || CDexConstants.isCDEX(program);
	}

	/* @Override */
	public AnalyzerType getAnalysisType() {
		return AnalyzerType.BYTE_ANALYZER;
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		return true;
	}

	/* @Override */
	public string getDescription() {
		return "Condenses all filler bytes in a DEX/CDEX file";
	}

	/* @Override */
	public string getName() {
		return "Android DEX/CDEX Condense Filler Bytes";
	}

	/* @Override */
	public AnalysisPriority getPriority() {
		return new AnalysisPriority(int.MaxValue);
	}

	/* @Override */
	public bool isPrototype() {
		return false;
	}

	private bool isRangeAllSameBytes(Program program, AddressRange addressRange, byte value,
			TaskMonitor monitor)
    {
		byte[] bytes = new byte[(int) addressRange.getLength()];
		try {
			program.getMemory().getBytes(addressRange.getMinAddress(), bytes);
		}
		catch (Exception e) {
			return false;
			//ignore
		}
		foreach (byte b in bytes) {
			monitor.checkCancelled();
			if (b != value) {
				return false;
			}
		}
		return true;
	}
}
